def transform(grid):
    out = [row[:] for row in grid]
    pos2 = pos8 = None
    rows5, cols5 = [], []
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value == 2:
                pos2 = (r, c)
            elif value == 8:
                pos8 = (r, c)
            elif value == 5:
                rows5.append(r)
                cols5.append(c)
    out[pos2[0]][pos2[1]] = 7
    out[pos8[0]][pos8[1]] = 2
    out[max(rows5)][max(cols5) + 1] = 8
    return out
